def digitCombinations(k, n):
    res = []
    cur = []

    def go(start, left, need):
        if left == 0:
            if need == 0:
                res.append(cur[:])
            return
        for d in range(start, 10):
            if d > need:
                break
            cur.append(d)
            go(d + 1, left - 1, need - d)
            cur.pop()

    go(1, k, n)
    return res
